INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'مطار القاهرة الدولي', 'multi', 'مترو الأنفاق + ميني باص المطار', 'bx bx-transfer', 25, '50 دقيقة', '["ادخل محطة مترو الشهداء بالخط الأول أو الثاني.", "توجه لمحطة العتبة أو جمال عبد الناصر وحوّل للخط الثالث (الأخضر).", "انزل في محطة (الأهرام بمصر الجديدة) أو محطة (النزهة).", "اخرج من محطة الأهرام بمصر الجديدة أو النزهة.", "اركب ميني باص المطار أو أتوبيس CTA المتجه مباشرة لصالات السفر (صالة 1 أو 2 أو 3).", "النزول أمام الصالة المطلوبة مباشرة واستخدام شاتل باص المطار المجاني للتنقل بين الصالات."]'::jsonb, '[{"title": "المرحلة الأولى: مترو الأنفاق من الشهداء إلى العباسية أو الأهرام", "vehicleType": "مترو الأنفاق", "cost": 10, "duration": "25 دقيقة", "steps": ["ادخل محطة مترو الشهداء بالخط الأول أو الثاني.", "توجه لمحطة العتبة أو جمال عبد الناصر وحوّل للخط الثالث (الأخضر).", "انزل في محطة (الأهرام بمصر الجديدة) أو محطة (النزهة)."]}, {"title": "المرحلة الثانية: أتوبيس أو ميكروباص المطار المباشر", "vehicleType": "أتوبيس نقل عام", "cost": 15, "duration": "25 دقيقة", "steps": ["اخرج من محطة الأهرام بمصر الجديدة أو النزهة.", "اركب ميني باص المطار أو أتوبيس CTA المتجه مباشرة لصالات السفر (صالة 1 أو 2 أو 3).", "النزول أمام الصالة المطلوبة مباشرة واستخدام شاتل باص المطار المجاني للتنقل بين الصالات."]}]'::jsonb, 'أسرع طريقة وتتجنب زحمة كوبري 6 أكتوبر وصلاح سالم تماماً.', 'رمسيس, محطة مصر, ميدان رمسيس, الشهداء, الفجالة', 'مطار القاهره, المطار, صالة 1, صالة 2, صالة 3, تيرمينال, Cairo Airport')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'مطار القاهرة الدولي', 'bus', 'أتوبيس هيئة النقل العام المباشر (111 أو 381)', 'bx bx-bus', 15, 'ساعة و 15 دقيقة', '["توجه لموقف أتوبيسات هيئة النقل العام بميدان رمسيس خلف مسجد الفتح.", "اركب أتوبيس رقم 111 أو خط 381 أو خط 555 المتجه للمطار.", "السير عبر شارع رمسيس، غمرة، العباسية، ومحور صلاح سالم ومصر الجديدة.", "النزول في موقف المطار الداخلي أمام صالة 1 القديمة أو صالة 3 الجديدة."]'::jsonb, '[{"title": "أتوبيس مباشر من ميدان رمسيس إلى صالات المطار", "vehicleType": "أتوبيس هيئة النقل العام", "cost": 15, "duration": "ساعة و 15 دقيقة", "steps": ["توجه لموقف أتوبيسات هيئة النقل العام بميدان رمسيس خلف مسجد الفتح.", "اركب أتوبيس رقم 111 أو خط 381 أو خط 555 المتجه للمطار.", "السير عبر شارع رمسيس، غمرة، العباسية، ومحور صلاح سالم ومصر الجديدة.", "النزول في موقف المطار الداخلي أمام صالة 1 القديمة أو صالة 3 الجديدة."]}]'::jsonb, 'متوفر أمام محطة مصر مباشرة، اقتصادي جداً ومناسب لمن يحمل حقائب خفيفة.', 'رمسيس, محطة مصر, ميدان رمسيس, الشهداء, الفجالة', 'مطار القاهره, المطار, صالة 1, صالة 2, صالة 3, تيرمينال, Cairo Airport')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'مطار القاهرة الدولي', 'car', 'تاكسي أو سيارة خاصة / أوبر', 'bx bx-car', 180, '40 دقيقة', '["الصعود لكوبري 6 أكتوبر من مطلع رمسيس باتجاه مدينة نصر ومصر الجديدة.", "النزول في منزل طريق النصر باتجاه ميدان هشام بركات وصلاح سالم.", "استكمال المسار عبر كوبري المطار حتى صالات المغادرة أو الوصول مباشرة."]'::jsonb, '[{"title": "سيارة خاصة عبر كوبري 6 أكتوبر وصلاح سالم", "vehicleType": "سيارة خاصة / تاكسي", "cost": 180, "duration": "40 دقيقة", "steps": ["الصعود لكوبري 6 أكتوبر من مطلع رمسيس باتجاه مدينة نصر ومصر الجديدة.", "النزول في منزل طريق النصر باتجاه ميدان هشام بركات وصلاح سالم.", "استكمال المسار عبر كوبري المطار حتى صالات المغادرة أو الوصول مباشرة."]}]'::jsonb, 'في أوقات الذروة الصباحية وبعد الظهر، اسلك كوبري أكتوبر ثم محور النصر وطريق العروبة.', 'رمسيس, محطة مصر, ميدان رمسيس, الشهداء, الفجالة', 'مطار القاهره, المطار, صالة 1, صالة 2, صالة 3, تيرمينال, Cairo Airport')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('الجيزة', 'مطار القاهرة الدولي', 'multi', 'مترو الأنفاق (خط 2 ثم خط 3) + أتوبيس المطار', 'bx bx-transfer', 30, 'ساعة و 10 دقائق', '["اركب المترو من محطة الجيزة (الخط الثاني اتجاه شبرا الخيمة).", "التبديل في محطة العتبة للخط الثالث (الأخضر) اتجاه عدلي منصور.", "النزول في محطة هليوبوليس أو هارون أو النزهة بمصر الجديدة.", "الخروج للشارع الرئيسي أمام محطة النزهة وركوب ميكروباص المطار.", "الوصول المباشر لصالات السفر والوصول بمطار القاهرة."]'::jsonb, '[{"title": "المرحلة الأولى: مترو من الجيزة إلى العتبة ثم مصر الجديدة", "vehicleType": "مترو الأنفاق", "cost": 15, "duration": "40 دقيقة", "steps": ["اركب المترو من محطة الجيزة (الخط الثاني اتجاه شبرا الخيمة).", "التبديل في محطة العتبة للخط الثالث (الأخضر) اتجاه عدلي منصور.", "النزول في محطة هليوبوليس أو هارون أو النزهة بمصر الجديدة."]}, {"title": "المرحلة الثانية: ميني باص المطار السريع", "vehicleType": "ميكروباص / أتوبيس", "cost": 15, "duration": "30 دقيقة", "steps": ["الخروج للشارع الرئيسي أمام محطة النزهة وركوب ميكروباص المطار.", "الوصول المباشر لصالات السفر والوصول بمطار القاهرة."]}]'::jsonb, 'تجنب تماماً الزحام الخانق على كوبري عباس والجيزة وصلاح سالم.', 'ميدان الجيزة, محطة الجيزة, فيصل, الهرم', 'مطار القاهره, المطار, صالة 1, صالة 2, صالة 3, Cairo Airport')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('الجيزة', 'مطار القاهرة الدولي', 'microbus', 'ميكروباص دائري من موقف المنيب / الجيزة إلى موقف السلام ثم المطار', 'bx bx-bus', 35, 'ساعة و 20 دقيقة', '["اركب ميكروباص (دائري - السلام) من موقف الجيزة أو المنيب.", "النزول عند تقاطع المطار على الطريق الدائري أو موقف السلام.", "ركوب سيارة ميكروباص المطار أو أتوبيس 111 للصالات."]'::jsonb, '[{"title": "ميكروباص الدائري السريع إلى موقف السلام ثم المطار", "vehicleType": "ميكروباص", "cost": 35, "duration": "ساعة و 20 دقيقة", "steps": ["اركب ميكروباص (دائري - السلام) من موقف الجيزة أو المنيب.", "النزول عند تقاطع المطار على الطريق الدائري أو موقف السلام.", "ركوب سيارة ميكروباص المطار أو أتوبيس 111 للصالات."]}]'::jsonb, 'مناسب لمن يفضل المواصلات المباشرة دون دخول وسط القاهرة.', 'ميدان الجيزة, محطة الجيزة, فيصل, الهرم', 'مطار القاهره, المطار, صالة 1, صالة 2, صالة 3, Cairo Airport')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'مطار سفنكس الدولي', 'multi', 'مترو الأنفاق + ميكروباص طريق إسكندرية الصحراوي', 'bx bx-transfer', 45, 'ساعة و 15 دقيقة', '["اركب مترو الخط الثالث من العتبة أو ناصر حتى محطة (محور روض الفرج) أو (الكيت كات).", "الخروج للشارع الرئيسي باتجاه مواقف غرب القاهرة.", "اركب عربيات السليمانية أو الخطاطبة أو وادي النطرون المارة بطريق إسكندرية الصحراوي.", "اطلب النزول أمام بوابة مطار سفنكس الدولي مباشرة بالكيلو 45.", "الدخول عبر البوابة الأمنية للمطار واستقلال حافلة الصالة الداخلية."]'::jsonb, '[{"title": "المرحلة الأولى: مترو إلى الكيت كات أو محور روض الفرج", "vehicleType": "مترو الأنفاق", "cost": 12, "duration": "25 دقيقة", "steps": ["اركب مترو الخط الثالث من العتبة أو ناصر حتى محطة (محور روض الفرج) أو (الكيت كات).", "الخروج للشارع الرئيسي باتجاه مواقف غرب القاهرة."]}, {"title": "المرحلة الثانية: ميكروباص إسكندرية الصحراوي / السليمانية", "vehicleType": "ميكروباص", "cost": 33, "duration": "50 دقيقة", "steps": ["اركب عربيات السليمانية أو الخطاطبة أو وادي النطرون المارة بطريق إسكندرية الصحراوي.", "اطلب النزول أمام بوابة مطار سفنكس الدولي مباشرة بالكيلو 45.", "الدخول عبر البوابة الأمنية للمطار واستقلال حافلة الصالة الداخلية."]}]'::jsonb, 'يقع مطار سفنكس عند الكيلو 45 على طريق مصر - الإسكندرية الصحراوي بعد الشيخ زايد.', 'رمسيس, محطة مصر, الشهداء', 'مطار سفنكس, Sphinx Airport, مطار الشيخ زايد, مطار غرب القاهرة')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'مطار سفنكس الدولي', 'car', 'سيارة خاصة / أوبر عبر محور 26 يوليو ومحور الضبعة', 'bx bx-car', 250, '45 دقيقة', '["التحرك من رمسيس عبر كوبري 6 أكتوبر وصولاً لمطلع محور روض الفرج.", "السير على طريق مصر إسكندرية الصحراوي حتى الوصول لمطار سفنكس."]'::jsonb, '[{"title": "سيارة خاصة عبر كوبري تحيا مصر ومحور روض الفرج", "vehicleType": "سيارة خاصة", "cost": 250, "duration": "45 دقيقة", "steps": ["التحرك من رمسيس عبر كوبري 6 أكتوبر وصولاً لمطلع محور روض الفرج.", "السير على طريق مصر إسكندرية الصحراوي حتى الوصول لمطار سفنكس."]}]'::jsonb, 'المسار الأسرع عبر محور روض الفرج الجديد ثم طريق إسكندرية الصحراوي.', 'رمسيس, محطة مصر, الشهداء', 'مطار سفنكس, Sphinx Airport, مطار الشيخ زايد, مطار غرب القاهرة')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'محطة قطارات صعيد مصر (بشتيل)', 'microbus', 'ميكروباص مباشر من أحمد عرابي / رمسيس', 'bx bx-bus', 8, '20 دقيقة', '["توجه لموقف أحمد عرابي خلف محطة مصر برمسيس.", "اركب ميكروباص (بشتيل - إمبابة).", "انزل أمام مبنى المحطة الذكية العملاق الجديد مباشرة."]'::jsonb, '[{"title": "ميكروباص مباشر إلى بوابة محطة قطارات صعيد مصر", "vehicleType": "ميكروباص", "cost": 8, "duration": "20 دقيقة", "steps": ["توجه لموقف أحمد عرابي خلف محطة مصر برمسيس.", "اركب ميكروباص (بشتيل - إمبابة).", "انزل أمام مبنى المحطة الذكية العملاق الجديد مباشرة."]}]'::jsonb, 'محطة بشتيل تقع في منطقة بشتيل وإمبابة وقريبة جداً من كوبري 15 مايو وشارع السودان.', 'رمسيس, محطة مصر', 'بشتيل, محطة بشتيل, قطارات الصعيد الجديدة, محطة قطار بشتيل')
ON CONFLICT DO NOTHING;

