INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (التحرير)', 'محطة عدلي منصور المركزية التبادلية', 'metro', 'مترو الأنفاق المباشر (الخط الثالث الأخضر)', 'bx bx-subway', 15, '40 دقيقة', '["اركب من محطة أنور السادات (الخط الأول) لمحطة جمال عبد الناصر (محطة واحدة).", "حوّل لرصيف الخط الثالث (الأخضر) المتجه مباشرة إلى محطة عدلي منصور النهائية.", "النزول داخل مجمع محطة عدلي منصور التبادلي المكيف."]'::jsonb, '[{"title": "مترو الأنفاق من أنور السادات إلى عدلي منصور", "vehicleType": "مترو الأنفاق", "cost": 15, "duration": "40 دقيقة", "steps": ["اركب من محطة أنور السادات (الخط الأول) لمحطة جمال عبد الناصر (محطة واحدة).", "حوّل لرصيف الخط الثالث (الأخضر) المتجه مباشرة إلى محطة عدلي منصور النهائية.", "النزول داخل مجمع محطة عدلي منصور التبادلي المكيف."]}]'::jsonb, 'أسهل وسيلة: من التحرير اركب مترو السادات حتى ناصر وحوّل للخط الثالث مباشرة لعدلي منصور.', 'التحرير, ميدان التحرير, السادات, وسط البلد', 'عدلي منصور, موقف السلام, LRT, القطار الكهربائي الخفيف, محطة السلام')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (التحرير)', 'محطة عدلي منصور المركزية التبادلية', 'bus', 'أتوبيس النقل العام من التحرير (عبد المنعم رياض)', 'bx bx-bus', 12, 'ساعة', '["توجه لموقف عبد المنعم رياض بالتحرير.", "اركب أتوبيس خط السلام أو العاشر من رمضان المار بعدلي منصور.", "السير عبر كوبري 6 أكتوبر، العباسية، جسر السويس وصولاً لموقف عدلي منصور."]'::jsonb, '[{"title": "أتوبيس هيئة النقل العام إلى موقف السلام وعدلي منصور", "vehicleType": "أتوبيس نقل عام", "cost": 12, "duration": "ساعة", "steps": ["توجه لموقف عبد المنعم رياض بالتحرير.", "اركب أتوبيس خط السلام أو العاشر من رمضان المار بعدلي منصور.", "السير عبر كوبري 6 أكتوبر، العباسية، جسر السويس وصولاً لموقف عدلي منصور."]}]'::jsonb, 'ينطلق من موقف عبد المنعم رياض خلف المتحف المصري بالتحرير.', 'التحرير, ميدان التحرير, السادات, وسط البلد', 'عدلي منصور, موقف السلام, LRT, القطار الكهربائي الخفيف, محطة السلام')
