INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'العاصمة الإدارية الجديدة', 'multi', 'مترو الأنفاق + القطار الكهربائي الخفيف (LRT)', 'bx bx-train', 40, 'ساعة و 10 دقائق', '["اركب المترو من محطة الشهداء لمحطة ناصر وحوّل للخط الثالث الأخضر.", "استمر حتى نهاية الخط في محطة (عدلي منصور المركزية).", "اصعد لرصيف قطار LRT داخل محطة عدلي منصور.", "اركب قطار العاصمة الإدارية (يمر بمدينة العبور، الشروق، بدر، وحدائق العاصمة).", "انزل في محطة (مدينة الفنون والثقافة) أو محطة (الحي الحكومي) بالعاصمة الإدارية."]'::jsonb, '[{"title": "المرحلة الأولى: مترو من رمسيس لمحطة عدلي منصور التبادلية", "vehicleType": "مترو الأنفاق (الخط الثالث)", "cost": 15, "duration": "35 دقيقة", "steps": ["اركب المترو من محطة الشهداء لمحطة ناصر وحوّل للخط الثالث الأخضر.", "استمر حتى نهاية الخط في محطة (عدلي منصور المركزية)."]}, {"title": "المرحلة الثانية: القطار الكهربائي السريع (LRT)", "vehicleType": "القطار الكهربائي الخفيف LRT", "cost": 25, "duration": "35 دقيقة", "steps": ["اصعد لرصيف قطار LRT داخل محطة عدلي منصور.", "اركب قطار العاصمة الإدارية (يمر بمدينة العبور، الشروق، بدر، وحدائق العاصمة).", "انزل في محطة (مدينة الفنون والثقافة) أو محطة (الحي الحكومي) بالعاصمة الإدارية."]}]'::jsonb, 'أرقى وأحدث وسيلة سفر مكيفة وسريعة بدون أي إشارات أو زحام مروري.', 'رمسيس, محطة مصر, وسط البلد', 'العاصمة الادارية, الحي الحكومي, البرج الأيقوني, النهر الأخضر, مسجد الفتاح العليم, كاتدرائية ميلاد المسيح, New Capital')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'العاصمة الإدارية الجديدة', 'bus', 'أتوبيسات العاصمة الإدارية المباشرة (شركة مواصلات مصر / CTA)', 'bx bx-bus', 35, 'ساعة و 25 دقيقة', '["اركب من موقف أحمد حلمي أو رمسيس أتوبيس العاصمة الإدارية المباشر.", "السير عبر طريق السويس السريع ومحور محمد بن زايد الشمالي.", "النزول في محطة الوزارات بالحي الحكومي أو أمام ساحة الشعب."]'::jsonb, '[{"title": "أتوبيس مباشر من رمسيس للحي الحكومي والبرج الأيقوني", "vehicleType": "أتوبيس نقل ذكي", "cost": 35, "duration": "ساعة و 25 دقيقة", "steps": ["اركب من موقف أحمد حلمي أو رمسيس أتوبيس العاصمة الإدارية المباشر.", "السير عبر طريق السويس السريع ومحور محمد بن زايد الشمالي.", "النزول في محطة الوزارات بالحي الحكومي أو أمام ساحة الشعب."]}]'::jsonb, 'مكيفة ومجهزة بشواحن وشاشات وتنطلق من أمام محطة مصر وموقف أحمد حلمي.', 'رمسيس, محطة مصر, وسط البلد', 'العاصمة الادارية, الحي الحكومي, البرج الأيقوني, النهر الأخضر, مسجد الفتاح العليم, كاتدرائية ميلاد المسيح, New Capital')
ON CONFLICT DO NOTHING;

