INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (التحرير)', 'التجمع الخامس (شارع التسعين)', 'bus', 'أتوبيس مواصلات مصر المكيف (M5 أو M6)', 'bx bx-bus', 20, '55 دقيقة', '["توجه لموقف عبد المنعم رياض بالتحرير.", "اركب خط M5 أو M6 المتجه للتجمع الخامس والجامعة الأمريكية.", "السير عبر كوبري 6 أكتوبر، محور المشير طنطاوي، مدخل كايرو فيستيفال، وشارع التسعين.", "النزول أمام مول الداون تاون، ميتينج بوينت، كونكورد بلازا، أو الجامعة الأمريكية."]'::jsonb, '[{"title": "أتوبيس مباشر من عبد المنعم رياض إلى شارع التسعين بالتجمع", "vehicleType": "أتوبيس مواصلات مصر", "cost": 20, "duration": "55 دقيقة", "steps": ["توجه لموقف عبد المنعم رياض بالتحرير.", "اركب خط M5 أو M6 المتجه للتجمع الخامس والجامعة الأمريكية.", "السير عبر كوبري 6 أكتوبر، محور المشير طنطاوي، مدخل كايرو فيستيفال، وشارع التسعين.", "النزول أمام مول الداون تاون، ميتينج بوينت، كونكورد بلازا، أو الجامعة الأمريكية."]}]'::jsonb, 'الأتوبيس مكيف بالكامل ويوفر واي فاي مجاني ويمر بطول شارع التسعين بالكامل.', 'التحرير, وسط البلد, عبد المنعم رياض', 'التجمع الخامس, شارع التسعين, التسعين الشمالي, التسعين الجنوبي, الجامعة الأمريكية, الداون تاون, New Cairo, 5th Settlement')
ON CONFLICT DO NOTHING;

INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
