VALUES ('القاهرة (رمسيس)', 'مدينة الشيخ زايد', 'microbus', 'ميكروباص مباشر من رمسيس إلى الشيخ زايد (هايبر وان)', 'bx bx-bus', 20, '40 دقيقة', '["اركب من موقف رمسيس ميكروباص (الشيخ زايد - هايبر).", "السير عبر محور 26 يوليو والنزول مباشرة أمام هايبر وان عند مدخل زايد الأول.", "ركوب سرفيس داخلي للوصول لمول أركان أو كابيتال بيزنس بارك أو بيفرلي هيلز."]'::jsonb, '[{"title": "ميكروباص من رمسيس عبر محور 26 يوليو إلى هايبر وان", "vehicleType": "ميكروباص", "cost": 20, "duration": "40 دقيقة", "steps": ["اركب من موقف رمسيس ميكروباص (الشيخ زايد - هايبر).", "السير عبر محور 26 يوليو والنزول مباشرة أمام هايبر وان عند مدخل زايد الأول.", "ركوب سرفيس داخلي للوصول لمول أركان أو كابيتال بيزنس بارك أو بيفرلي هيلز."]}]'::jsonb, 'أخبر السائق أن ينزلك عند هايبر وان أو مدخل زايد 1 أو أركان.', 'رمسيس, محطة مصر', 'الشيخ زايد, هايبر وان, هايبر, أركان بلازا, مول أركان, زايد 2000, Sheikh Zayed')
