INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'القرية الذكية (Smart Village)', 'microbus', 'ميكروباص مباشر من رمسيس (أحمد عرابي) إلى بوابة القرية الذكية', 'bx bx-bus', 25, '45 دقيقة', '["اركب من موقف أحمد عرابي برمسيس ميكروباص (القرية الذكية).", "السير على محور 26 يوليو وصولاً لبوابة القرية الذكية الكيلو 28 بطريق مصر إسكندرية الصحراوي.", "الدخول عبر البوابة واستخدام الأتوبيسات الداخلية للقرية مجاناً."]'::jsonb, '[{"title": "ميكروباص مباشر عبر محور 26 يوليو وطريق إسكندرية الصحراوي", "vehicleType": "ميكروباص", "cost": 25, "duration": "45 دقيقة", "steps": ["اركب من موقف أحمد عرابي برمسيس ميكروباص (القرية الذكية).", "السير على محور 26 يوليو وصولاً لبوابة القرية الذكية الكيلو 28 بطريق مصر إسكندرية الصحراوي.", "الدخول عبر البوابة واستخدام الأتوبيسات الداخلية للقرية مجاناً."]}]'::jsonb, 'متوفر بكثرة في ساعات الصباح الباكر لنقل موظفي وطلاب شركات وجامعات القرية الذكية.', 'رمسيس, محطة مصر', 'القرية الذكية, القريه الذكيه, سمارت فيلدج, Smart Village, طريق اسكندرية الصحراوي')
