INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'مدينة الشروق', 'multi', 'مترو الأنفاق + القطار الكهربائي الخفيف (LRT)', 'bx bx-train', 25, '50 دقيقة', '["اركب المترو بالخط الثالث حتى محطة عدلي منصور.", "اركب قطار LRT من عدلي منصور وانزل في محطة (الشروق).", "ركوب سرفيس الشروق الداخلي لوجهتك."]'::jsonb, '[{"title": "المرحلة الأولى: مترو إلى محطة عدلي منصور التبادلية", "vehicleType": "مترو الأنفاق", "cost": 10, "duration": "30 دقيقة", "steps": ["اركب المترو بالخط الثالث حتى محطة عدلي منصور."]}, {"title": "المرحلة الثانية: قطار LRT إلى محطة الشروق", "vehicleType": "قطار كهربائي LRT", "cost": 15, "duration": "20 دقيقة", "steps": ["اركب قطار LRT من عدلي منصور وانزل في محطة (الشروق).", "ركوب سرفيس الشروق الداخلي لوجهتك."]}]'::jsonb, 'قطار LRT يمتلك محطتين مخصصتين لمدينة الشروق (الشروق 1 والشروق 2).', 'رمسيس, محطة مصر', 'الشروق, مدينة الشروق, مدخل الشروق, طريق السويس, El Shorouk')
ON CONFLICT DO NOTHING;

