INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (التحرير)', 'قلعة صلاح الدين الأيوبي وجامع محمد علي', 'bus', 'أتوبيس هيئة النقل العام أو ميني باص السيدة عائشة', 'bx bx-bus', 10, '25 دقيقة', '["اركب ميني باص أو أتوبيس السيدة عائشة من موقف عبد المنعم رياض بالتحرير.", "النزول في ميدان السيدة عائشة أسفل كوبري القلعة.", "الصعود سيراً على الأقدام لمدة 5 دقائق لبوابة دخول قلعة صلاح الدين ومتحف الأسلحة وجامع محمد علي."]'::jsonb, '[{"title": "أتوبيس من التحرير إلى ميدان السيدة عائشة والقلعة", "vehicleType": "أتوبيس نقل عام", "cost": 10, "duration": "25 دقيقة", "steps": ["اركب ميني باص أو أتوبيس السيدة عائشة من موقف عبد المنعم رياض بالتحرير.", "النزول في ميدان السيدة عائشة أسفل كوبري القلعة.", "الصعود سيراً على الأقدام لمدة 5 دقائق لبوابة دخول قلعة صلاح الدين ومتحف الأسلحة وجامع محمد علي."]}]'::jsonb, 'القلعة قريبة جداً من ميدان السيدة عائشة ومسجد السلطان حسن والرفاعي.', 'التحرير, وسط البلد', 'القلعة, قلعة صلاح الدين, جامع محمد علي, متحف الشرطة, القلعه, Citadel')
