INSERT INTO public.transit_routes (from_location, to_location, type, type_name, icon, cost, duration, steps, legs, tips, from_aliases, to_aliases)
VALUES ('القاهرة (رمسيس)', 'خان الخليلي والحسين وشارع المعز', 'microbus', 'ميكروباص مباشر من رمسيس للحسين والأزهر', 'bx bx-bus', 6, '15 دقيقة', '["توجه لناحية كوبري أكتوبر برمسيس واركب ميكروباص (الحسين - الدراسة).", "السير عبر شارع رمسيس ثم نفق الأزهر.", "النزول أمام مستشفى الحسين الجامعي وميدان مسجد الإمام الحسين.", "الدخول مشياً لشارع المعز التاريخي وسوق خان الخليلي وباب زويلة."]'::jsonb, '[{"title": "ميكروباص من رمسيس إلى مشهد الحسين", "vehicleType": "ميكروباص", "cost": 6, "duration": "15 دقيقة", "steps": ["توجه لناحية كوبري أكتوبر برمسيس واركب ميكروباص (الحسين - الدراسة).", "السير عبر شارع رمسيس ثم نفق الأزهر.", "النزول أمام مستشفى الحسين الجامعي وميدان مسجد الإمام الحسين.", "الدخول مشياً لشارع المعز التاريخي وسوق خان الخليلي وباب زويلة."]}]'::jsonb, 'أسرع وأرخص طريقة: الميكروباص يقف عند مشفى الحسين الجامعي مباشرة أمام خان الخليلي.', 'رمسيس, محطة مصر', 'خان الخليلي, الحسين, شارع المعز, الازهر, جامع الازهر, باب الفتوح, باب النصر, Khan El Khalili')
ON CONFLICT DO NOTHING;

